//For the #wccChallenge on the theme of 'particle systems'.
//Ooops, I mean "nope".
//Particles are radiating from circles and drawing on the canvas, with
//their colors lerping through the color array via their current velocity.
//Meanwhile other overlapping circles push the particles away (saying nope), giving the piece
//it's composition.


let colors=["#94472f","#0e5264","#522829","#20283a","#c97a5a","#debe98"]


//A couple alternative palettes:

//very bright- orange and blue
//colors = ["#ffd283","#fdbb81","#d7ada7","#afd7ec","#7496b8"]

//more pencilly
//colors=["#E3DED5","#abaaa8","#cdb67b","#a07b42","#3d3b3a"]


let particles=[]
let shields=[]
let suns=[]
let shield, sun, dim
let maxSpeed= 2

function setup() {
	dim= max(windowWidth, windowHeight)
	createCanvas(dim, dim);
	blendMode(MULTIPLY)
	noFill()
	stroke(0)	
	background("#f8fce9");
	for(let i=0; i<4; i++){
sun= {
		pos:createVector(random(width*0.2, width*0.8), random(height*0.5, height*0.9)),
		radius: random(dim*0.01, dim*0.1)
}
		suns.push(sun)
}

sun={
	pos: createVector(random(width), height*0.1),
	radius: dim*0.05
}
	suns.push(sun)

		let m=width/6;
		for(let x=m/2; x<width; x+=m){
	let xoff= random(-m, m)
	let y= map(noise(Date.now(), x/100), 0, 1, 0, height*0.6)

 shield= {
	pos: createVector(x+xoff, y),
		radius: random(dim*0.05, dim*0.25)
	}
		shields.push(shield)
	}
}

function draw() {
for(let s of suns){	
	for(let i=0; i<10; i++){
		let a=random(TAU)
		let x=s.pos.x+ cos(a)*s.radius
		let y=s.pos.y+ sin(a)*s.radius
particles.push(new particle(x, y, a))	
	}
}

for(let p of particles){
	p.move();
	p.deflect();
	p.show();
	p.end();
}
}

class particle{
	constructor(x, y, a){
		this.pos=createVector(x, y)
		//this.acc=p5.Vector.random2D()
		this.acc=p5.Vector.fromAngle(a);
		this.acc.setMag(0.02)
		this.vel= createVector(0,0)
		this.color= random(colors)
	}

	move(){
		this.acc.limit(0.3)
		this.vel.limit(maxSpeed)
		this.vel.add(this.acc);
		this.pos.add(this.vel);

	}

	deflect(){

		for(let s of shields){
		let d=this.pos.dist(s.pos)
		if(d<s.radius*1.25){
		//print(this.vel.mag())
		let m= map(d, dim/4, 0, 0.0001, 0.005)
		let direction = p5.Vector.sub(this.pos, s.pos);
			direction.setMag(m)
			this.acc.add(direction)
		}
		}
	}

	show(){
		strokeWeight(0.5)
		//print(this.vel.mag())
		let c= colorMixer(this.vel.mag(), colors)

		stroke(c)
		point(this.pos.x, this.pos.y)


	}

	end(){
		if(this.pos.x>=width-10 || this.pos.x<=10 || this.pos.y<=10 ||this.pos.y>=height-10){
		 let index = particles.indexOf(this);
      particles.splice(index, 1);
		}
	}

}


function colorMixer(velocity, colorArray) {
	//let d= p5.Vector.dist(center, pos)
	let c = map(velocity, 0, maxSpeed, 0, colorArray.length)
	let c1 = floor(c)%colorArray.length
	let c2 = floor(c+1)%colorArray.length

	//spectral
	// let color1 = colorArray[c1]
	// let color2 = colorArray[c2]
	// let mix = fract(c)
	// let coloring = color(spectral.mix(color1, color2, mix))

	//lerp
	let color1 = color(colorArray[c1])
	let color2 = color(colorArray[c2])
	let mix = fract(c)
	let coloring = lerpColor(color1, color2, mix)


	return coloring
}

